# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.19.0/ankra-cli-darwin-arm64"
      sha256 "c0d749aad963942a3d46d39d5abbb287e3dbc114a16b7383fceb4fa6013b0785"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.19.0/ankra-cli-darwin-amd64"
      sha256 "79830ec15d7b49eec2c8a435d0723bfc810078a7b549e90a1b1dd7fd780775ec"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.19.0/ankra-cli-linux-arm64"
      sha256 "48b7c55734f36e04d73181822577ea85b40d141971534ed493b7321b3617c39d"
    end
    on_intel do
